    13	/*
    14	** Main entry point.  The fuzzer invokes this function with each
    15	** fuzzed input.
    16	*/
    17	extern "C" int
    18	LLVMFuzzerTestOneInput(uint8_t *data, size_t size) {
    19	    UA_ByteString buf;
    20	    buf.data = (UA_Byte*)data;
    21	    buf.length = size;
    22	
    23	    UA_Variant out;
    24	    UA_Variant_init(&out);
    25	
    26	    UA_StatusCode retval = UA_decodeJson(&buf, &out, &UA_TYPES[UA_TYPES_VARIANT]);
    27	    if(retval == UA_STATUSCODE_GOOD)
    28	        UA_Variant_deleteMembers(&out);
    29	
    30	    return 0;
    31	}
